// ============================================================
// NO: agenda leituras (por familia)   (servidor DSE - aba "Deep Sea -> REST /api/gerador")
// O QUE FAZ : a cada 1 s decide QUAIS blocos de registradores do DSE estao no
//             prazo de leitura e gera um pedido Modbus FC03 (somente leitura)
//             para cada um. Nada aqui escreve no controlador.
// ENTRADA   : tique do inject "a cada 1 s" (conteudo ignorado).
// SAIDA     : [[pedido, pedido, ...]] -> "Leitura DSE (blocos)" (modbus-flex-getter).
//             Cada pedido leva msg.bloco = id do bloco, usado na volta para decodificar.
// PARAMETROS (variaveis de ambiente da aba): DSE_MODELO (ex.: 4520) e DSE_UNIT_ID (10).
// CONTEXTO  : global.gerador_cfg (configuracao resolvida, usada pelos outros nos)
//             global.gerador_blk (estado de cada bloco: ult, pend, prox, falhas).
// PROTECOES : - nao repete pedido de bloco ainda sem resposta (ate 30 s) -> evita fila;
//             - respeita a suspensao de blocos opcionais que falharam (no de diagnostico);
//             - cada bloco tem seu periodo (v3.6: A e B = 2 s; demais 2 a 60 s).
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================
// Agendador de leituras (SOMENTE LEITURA, FC03). Roda a cada 1 s e dispara só o que está no prazo.
// O modelo do DSE vem do parâmetro DSE_MODELO (variável de ambiente da aba): número do modelo (ex.: 4520, 7420, 8620) ou chave de família.

// ================= FAMILIAS DE CONTROLADOR =================
// FAMS: para cada familia, qual tabela de alarmes nomeados (pagina 154) e qual
//       mapa de LEDs (pagina 190: "A" = 71xx/72xx/73xx, "B" = 74xx/8xxx) usar.
// MOD : numero do modelo -> familia. Modelo fora da lista = familia desconhecida
//       (o servidor continua lendo medidas, mas sem alarmes nomeados e LEDs).
// QA  : quantos registradores ler na pagina 154 por familia (registrador 0 + alarmes).
// QL  : quantos registradores ler na pagina 190 por mapa de LEDs.
const FAMS = { "4xxx": { alm: "4xxx", led: "A" }, "61xx": { alm: "61xx", led: "A" }, "72xx": { alm: "72xx", led: "A" },
  "73xx": { alm: "72xx", led: "A" }, "74xx": { alm: "72xx", led: "B" }, "8xxx": { alm: "8xxx", led: "B" }, "7450": { alm: "7450", led: null } };
const MOD = { 4510: "4xxx", 4520: "4xxx", 6010: "4xxx", 6020: "4xxx", 7110: "4xxx", 7120: "4xxx", 6110: "61xx", 6120: "61xx",
  7210: "72xx", 7220: "72xx", 7310: "73xx", 7320: "73xx", 7410: "74xx", 7420: "74xx", 8610: "8xxx", 8620: "8xxx", 8660: "8xxx", 7450: "7450" };
const QA = {"61xx": 16, "72xx": 21, "8xxx": 59, "7450": 28, "4xxx": 14};
const QL = { A: 16, B: 22 };

// ================= RESOLUCAO DO MODELO =================
// Aceita a chave da familia ("74xx") ou qualquer texto com 4 digitos ("DSE7420").
// O Unit ID padrao da DSE e 10; se a variavel estiver vazia ou invalida, usa 10.
const raw = String(env.get("DSE_MODELO") || "").trim().toLowerCase();
const chave = FAMS[raw] ? raw : (MOD[(raw.match(/\d{4}/) || [])[0]] || null);
const fam = chave ? FAMS[chave] : null;
const cfg = { modelo: raw || null, chave, alm: fam ? fam.alm : null, led: fam ? fam.led : null,
  alarmQty: fam ? QA[fam.alm] : 0, ledQty: fam && fam.led ? QL[fam.led] : 0,
  unitId: parseInt(env.get("DSE_UNIT_ID"), 10) || 10, mod: MOD };   // mod: usado na conferencia de modelo (v3.2)
global.set("gerador_cfg", cfg);

// ================= PLANO DE LEITURA (GenComm) =================
// Endereco = pagina x 256 + offset. ess = essencial (define ok/503 no JSON).
//  A  1024 pag. 4  instrumentacao basica: oleo, agua, bateria, rpm, Hz, tensoes, correntes, W por fase
//  B  1536 pag. 6  derivada: W/VA/var totais e por fase, FP, % carga
//  D   768 pag. 3  status: fabricante, modelo, serie, modo, flags de alarme
//  R  1073 pag. 4  rotacao de fases
//  C  1792 pag. 7  acumulados: relogio do DSE, horas de motor, energias, partidas
//  E 39424 pag.154 alarmes nomeados (4 por registrador, em nibbles)
//  L 48640 pag.190 LEDs e saidas digitais
//  J  4352 pag. 17 falhas da ECU (J1939 DTC)
//  G1 1280 / G2 1350 pag. 5  instrumentacao estendida da ECU (CAN)
//  V  2816 pag. 11 versao de firmware
//  S1 5152 / S2 5216 pag. 20 textos de modelo e variante (32 caracteres cada)
// id, endereço, quantidade, período (s), essencial, exige família conhecida
const BLOCOS = [
  { id: "A", addr: 1024, qty: 35, per: 2, ess: true },
  { id: "B", addr: 1536, qty: 24, per: 2, ess: true },
  { id: "D", addr: 768, qty: 7, per: 2 },
  { id: "R", addr: 1073, qty: 1, per: 5 },
  { id: "C", addr: 1792, qty: 18, per: 10 },
  { id: "E", addr: 39424, qty: cfg.alarmQty, per: 2, need: "alm" },
  { id: "L", addr: 48640, qty: cfg.ledQty, per: 2, need: "led" },
  { id: "J", addr: 4352, qty: 22, per: 5 },
  { id: "G1", addr: 1280, qty: 16, per: 10 },
  { id: "G2", addr: 1350, qty: 10, per: 10 },
  { id: "V", addr: 2816, qty: 1, per: 60 },
  { id: "S1", addr: 5152, qty: 32, per: 60 },
  { id: "S2", addr: 5216, qty: 32, per: 60 }
];

// ================= DESPACHO DOS PEDIDOS =================
// Para cada bloco, so gera pedido se: a familia permite, nao ha pedido pendente,
// o bloco nao esta suspenso e o periodo dele ja venceu.
// s.ult = hora do ultimo pedido; s.pend = pedido em andamento (zerado na resposta ou no erro).
const agora = Date.now();
const st = global.get("gerador_blk") || {};
const saida = [];
for (const b of BLOCOS) {
  if (b.need && !cfg[b.need]) continue;                 // família desconhecida: sem alarmes nomeados/LEDs
  const s = st[b.id] || (st[b.id] = {});
  if (s.pend && agora - s.pend < 30000) continue;      // pedido anterior ainda sem resposta (evita fila)
  if (s.prox && agora < s.prox) continue;              // bloco suspenso após falhas (tenta de novo depois)
  // v3.5/v3.6: tolerancia de 100 ms. O inject dispara "a cada 1 s" com jitter; sem folga, um tique 2-3 ms adiantado
  // seria pulado e o periodo real de um bloco de 2 s viraria 3 s.
  if (s.ult && agora - s.ult < b.per * 1000 - 100) continue;
  s.ult = agora; s.pend = agora;
  // Formato esperado pelo modbus-flex-getter: fc 3 = Read Holding Registers.
  saida.push({ bloco: b.id, topic: b.id, payload: { fc: 3, unitid: cfg.unitId, address: b.addr, quantity: b.qty } });
}
global.set("gerador_blk", st);
// Varias mensagens pela mesma saida; nenhuma se nada estiver no prazo.
return saida.length ? [saida] : null;

// ============================================================
// NO: monitor de queda (alerta inteligente)
// O QUE FAZ : acompanha se o DSE esta comunicando (mesma regra do "ok" da API:
//             blocos essenciais A e B lidos ha no maximo 10 s) e SO GERA MENSAGEM
//             quando o estado MUDA (queda -> recuperacao ou recuperacao -> queda).
//             Enquanto nada muda, nao sai nada - nao gera loop no debug.
// LEMBRETE  : opcional, repete o aviso de queda a cada LEMBRETE_MIN minutos
//             enquanto o DSE continuar fora do ar (0 = desliga o lembrete).
// ENTRADA   : mesmo tique de 1 s do agendador (gen_tick) - roda em paralelo,
//             nao interfere na leitura Modbus.
// SAIDA     : msg so nas transicoes (ou no lembrete). Ex.:
//             "DSE parou de comunicar. Ultimo erro: timeout (bloco A) as 14:32:05"
//             "DSE voltou a comunicar (ficou 00:03:12 fora do ar)"
// STATUS    : tambem desenha o estado no proprio no (bolinha verde/vermelha),
//             pra ver de relance no editor sem abrir o debug.
// VERSAO 3.4: no novo (monitor de queda), nao existia nas versoes anteriores.
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================
const LEMBRETE_MIN = 5; // minutos entre lembretes enquanto caido; 0 = so avisa na queda e na volta

const g = global.get("gerador_raw") || {};
const ts = g._ts || {};
const agora = Date.now();
const idadeSeg = t => t ? (agora - t) / 1000 : null;
const idA = idadeSeg(ts.A), idB = idadeSeg(ts.B);
const idade = (idA === null || idB === null) ? null : Math.max(idA, idB);
const ok = idade !== null && idade <= 10;

const d = global.get("gerador_diag") || {};
const m = global.get("gerador_mon") || { ok: null, desde: null, lembrete: null };

const fmtDur = (ms) => {
  const s = Math.max(0, Math.round(ms / 1000));
  const hh = String(Math.floor(s / 3600)).padStart(2, "0");
  const mm = String(Math.floor((s % 3600) / 60)).padStart(2, "0");
  const ss = String(s % 60).padStart(2, "0");
  return hh + ":" + mm + ":" + ss;
};
const ultimoErro = () => {
  if (d.ultimoErro) {
    // existe um erro de LEITURA registrado (timeout, excecao Modbus, etc.)
    return d.ultimoErro +
      (d.ultimoErroBloco ? " (bloco " + d.ultimoErroBloco + ")" : "") +
      (d.ultimoErroEm ? " às " + new Date(d.ultimoErroEm).toLocaleTimeString("pt-BR") : "");
  }
  if (d.status) {
    // sem erro de leitura, mas ha status de CONEXAO (ex.: TCP caiu) -> usa isso
    return "status da conexão: \"" + d.status + "\"" +
      (d.statusEm ? " desde " + new Date(d.statusEm).toLocaleTimeString("pt-BR") : "");
  }
  return "nenhum erro nem status registrado ainda (verifique a conexão TCP com o DSE, IP/porta no nó \"DSE (TCP)\")";
};

if (m.ok === ok) {
  // sem mudanca de estado
  if (!ok) {
    node.status({ fill: "red", shape: "ring", text: "sem DSE há " + fmtDur(agora - m.desde) });
    if (LEMBRETE_MIN > 0 && (!m.lembrete || agora - m.lembrete >= LEMBRETE_MIN * 60000)) {
      m.lembrete = agora;
      global.set("gerador_mon", m);
      msg.topic = "DSE";
      msg.payload = "⚠ DSE ainda sem comunicação há " + fmtDur(agora - m.desde) + ". Último erro: " + ultimoErro();
      return msg;
    }
  } else {
    node.status({ fill: "green", shape: "dot", text: "DSE ok" });
  }
  return null; // nada mudou: nao gera mensagem (evita o loop a cada segundo)
}

// ---- mudanca de estado: sempre avisa, e reinicia o cronometro do lembrete
const duracao = m.desde ? fmtDur(agora - m.desde) : null;
m.ok = ok; m.desde = agora; m.lembrete = ok ? null : agora;
global.set("gerador_mon", m);

msg.topic = "DSE";
if (ok) {
  node.status({ fill: "green", shape: "dot", text: "DSE ok" });
  msg.payload = "✔ DSE voltou a comunicar" + (duracao ? " (ficou " + duracao + " fora do ar)" : "") + ".";
} else {
  node.status({ fill: "red", shape: "ring", text: "sem DSE" });
  msg.payload = "✖ DSE parou de comunicar. Último erro: " + ultimoErro();
}
return msg;

// ============================================================
// NO: decodifica blocos   (servidor DSE)
// O QUE FAZ : recebe a resposta de UM bloco Modbus (msg.bloco + array de
//             registradores em msg.payload), converte para grandezas de engenharia
//             e guarda em global.gerador_raw. Nao responde HTTP: o no "monta JSON"
//             le esse contexto quando alguem chama GET /api/gerador.
// REGRAS GenComm aplicadas (fonte: GenComm v2.267):
//   - 32 bits: registrador de endereco menor = palavra ALTA (MSW*65536 + LSW);
//   - sentinelas (0xFFFF, 0x7FFF, 0xFFFFFFFF...) viram null, nunca numero;
//   - alarmes da pagina 154: 4 alarmes por registrador, 1 nibble cada.
// ESTRUTURA : parte 1 = funcoes puras de decodificacao (biblioteca);
//             parte 2 = tabelas de alarmes por familia;
//             parte 3 = decodificacao do bloco recebido (switch por id).
// SAIDA     : nenhuma (wire vazio). Marca o bloco como respondido (pend = 0,
//             falhas = 0) e grava o horario da leitura em gerador_raw._ts[id].
// VERSAO 3.2: alarmes limitados pelo registrador 0 (C9) e familia do texto de modelo (V1).
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================

// ================= PARTE 1 - BIBLIOTECA DE DECODIFICACAO =================
// Decodificador GenComm (DSE) — funções puras, sem dependências.
// Uso em nó "function" do Node-RED: copie o corpo, ou use module.exports em testes.
// Fonte das regras: GenComm v2.267 AD (ver references/01-protocolo-e-enderecamento.md).

// Sentinelas: valor máximo do tipo = "não implementado"; abaixo, os demais estados.
const SENT_NAMES = ["unimplemented", "over", "under", "transducer_fault", "bad_data", "digital_high", "digital_low", "reserved"];

// Retorna {value|null, status} para um valor cru já combinado.
// bits: 16|32 ; signed: boolean ; raw: número inteiro sem sinal (0..2^bits-1)
function decodeRaw(raw, bits, signed) {
  const top = bits === 16 ? 0xFFFF : 0xFFFFFFFF;
  const maxVal = signed ? (bits === 16 ? 0x7FFF : 0x7FFFFFFF) : top;
  // para 16S/32S o padrão de sentinelas parte do valor máximo positivo (ver doc); mantemos a mesma lógica
  if (signed) {
    const sraw = toSigned(raw, bits);
    for (let i = 0; i < 8; i++) if (sraw === maxVal - i) return { value: null, status: SENT_NAMES[i] };
    return { value: sraw, status: "ok" };
  }
  for (let i = 0; i < 8; i++) if (raw === top - i) return { value: null, status: SENT_NAMES[i] };
  return { value: raw, status: "ok" };
}

function toSigned(raw, bits) {
  const half = bits === 16 ? 0x8000 : 0x80000000;
  const full = bits === 16 ? 0x10000 : 0x100000000;
  return raw >= half ? raw - full : raw;
}

// 32 bits: registrador de endereço menor (par) = palavra alta. Multiplicar por 65536 (não 65535).
function combine32(msw, lsw) {
  return (msw & 0xFFFF) * 65536 + (lsw & 0xFFFF);
}

// Lê `regs` (array de números 0..65535) a partir de baseAddr; descreve o ponto {addr,bits,signed,scale}
function readPoint(regs, baseAddr, p) {
  const i = p.addr - baseAddr;
  let raw;
  if (p.bits === 32) raw = combine32(regs[i], regs[i + 1]);
  else raw = regs[i] & 0xFFFF;
  const d = decodeRaw(raw, p.bits, !!p.signed);
  if (d.value !== null && p.scale && p.scale !== 1) d.value = Math.round(d.value * p.scale * 1e6) / 1e6;
  return d;
}

// Alarmes nomeados (página 154): 4 nibbles por registrador; nibble mais significativo = alarme de menor índice.
// Retorna array de códigos (0..15) para os 4 alarmes do registrador.
function alarmNibbles(reg) {
  return [(reg >> 12) & 0xF, (reg >> 8) & 0xF, (reg >> 4) & 0xF, reg & 0xF];
}
const ALARM_CODES = {
  0: "disabled", 1: "normal", 2: "warning", 3: "shutdown", 4: "electrical_trip",
  5: "controlled_shutdown", 8: "indication_inactive_nostring", 9: "indication_inactive", 10: "indication_active", 15: "unimplemented",
};
function alarmName(code) { return ALARM_CODES[code] || "reserved"; }

// Flags de status (página 3, registrador 6 = endereço 774). Bit "n/16" => máscara 1<<(n-1).
// ATENÇÃO: os manuais 057-263/057-301 trocam Warning/Electrical trip no pseudo-código; aqui seguimos o GenComm.
function decodeStatusFlags(reg) {
  const b = (n) => ((reg >> (n - 1)) & 1) === 1;
  return {
    control_unit_not_configured: b(16), control_unit_failure: b(14),
    shutdown: b(13), electrical_trip: b(12), warning: b(11),
    telemetry: b(10), satellite_telemetry: b(9), controlled_shutdown: b(7),
  };
}

// Chave de controle: FC16 nos registradores 4104/4105 com (chave, 65535-chave), chave = 35700 + função.
function controlKeyWords(fn) {
  const k = 35700 + fn;
  return [k, 65535 - k];
}




// ================= PARTE 2 - TABELAS DE ALARMES (PAGINA 154) =================
// ALARMES[familia][registrador] = 4 nomes, na ordem dos nibbles (do mais
// significativo para o menos). null = posicao sem alarme nessa familia.
// Texto em ingles, como no manual DSE, para facilitar a busca no GenComm.
// Decodifica o bloco recebido (msg.bloco) e guarda em global.gerador_raw. Tabelas de alarme por família embutidas.
const ALARMES = {"61xx":{"1":["Emergency stop","Low oil pressure","High coolant temperature","Low coolant temperature"],"2":["Under speed","Over speed","Generator Under frequency","Generator Over frequency"],"3":["Generator low voltage","Generator high voltage","Battery low voltage","Battery high voltage"],"4":["Charge alternator failure","Fail to start","Fail to stop","Generator fail to close"],"5":["Mains fail to close","Oil pressure sender fault","Loss of magnetic pick up","Magnetic pick up open circuit"],"6":["Generator high current","Calibration lost","Low fuel level","CAN ECU Warning"],"7":["CAN ECU Shutdown","CAN ECU Data fail","Low oil level switch","High temperature switch"],"8":["Low fuel level switch","Expansion unit watchdog alarm","kW overload alarm",null],"9":[null,null,null,"Maintenance alarm"],"10":["Loading frequency alarm","Loading voltage alarm",null,null],"12":[null,null,"ECU protect","ECU Malfunction"],"13":["ECU Information","ECU Shutdown","ECU Warning","ECU HEST (was ECU Electrical Trip)"],"14":[null,"ECU Water In Fuel",null,null],"15":[null,"High fuel level","DEF Level Low","SCR Inducement"]},"72xx":{"1":["Emergency stop","Low oil pressure","High coolant temperature","Low coolant temperature"],"2":["Under speed","Over speed","Generator Under frequency","Generator Over frequency"],"3":["Generator low voltage","Generator high voltage","Battery low voltage","Battery high voltage"],"4":["Charge alternator failure","Fail to start","Fail to stop","Generator fail to close"],"5":["Mains fail to close","Oil pressure sender fault","Loss of magnetic pick up","Magnetic pick up open circuit"],"6":["Generator high current","Calibration lost","Low fuel level","CAN ECU Warning"],"7":["CAN ECU Shutdown","CAN ECU Data fail","Low oil level switch","High temperature switch"],"8":["Low fuel level switch","Expansion unit watchdog alarm","kW overload alarm","Negative phase sequence current alarm"],"9":["Earth fault trip alarm","Generator phase rotation alarm","Auto Voltage Sense Fail","Maintenance alarm"],"10":["Loading frequency alarm","Loading voltage alarm","Fuel usage running","Fuel usage stopped"],"11":["Protections disabled","Protections blocked","Generator Short Circuit","Mains High Current"],"12":["Mains Earth Fault","Mains Short Circuit","ECU protect","ECU Malfunction"],"13":["ECU Information","ECU Shutdown","ECU Warning","ECU Electrical Trip"],"14":["ECU After treatment","ECU Water In Fuel","Generator Reverse Power","Generator Positive VAr"],"15":["Generator Negative VAr","LCD Heater Low Voltage","LCD Heater High Voltage","DEF Level Low"],"16":["SCR Inducement","MSC Old version","MSC ID alarm","MSC failure"],"17":["MSC priority Error","Fuel Sender open circuit","Over speed runaway","Over frequency run away"],"18":["Coolant sensor open circuit","Remote display link lost","Fuel tank bund level","Charge air temperature"],"19":["Fuel level high","Gen breaker failed to open (v5.0+)","Mains breaker failed to open (v5.0+) – 7x20 only","Fail to synchronise (v5.0+) – 7x20 only"],"20":["AVR Data Fail (v5.0+)","AVR DM1 Red Stop Lamp (v5.0+)","Escape Mode (v5.0+)","Coolant high temp electrical trip (v5.0+)"]},"8xxx":{"1":["Emergency stop","Low oil pressure","High coolant temperature","Low coolant temperature"],"2":["Under speed","Over speed","Generator Under frequency","Generator Over frequency"],"3":["Generator low voltage","Generator high voltage","Battery low voltage","Battery high voltage"],"4":["Charge alternator failure","Fail to start","Fail to stop","Generator fail to close"],"5":["Mains fail to close","Oil pressure sender fault","Loss of magnetic pick up","Magnetic pick up open circuit"],"6":["Generator high current","Calibration lost","Low fuel level","CAN ECU Warning"],"7":["CAN ECU Shutdown","CAN ECU Data fail","Low oil level switch","High temperature switch"],"8":["Low fuel level switch","Expansion unit watchdog alarm","kW overload alarm","Negative phase sequence current alarm"],"9":["Earth fault trip alarm","Gener